import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { ProductVideoModel, AddOrUpdateProductVideoModel } from 'src/app/data/model/product/AddOrUpdateProductModel';
import { IProductDetailModel, ProductDetailModel } from 'src/app/data/model/product/ProductDetailModel';
import { IProductFilterModel, ProductFilterModel } from 'src/app/data/model/product/ProductFilterModel';
import { IProductModel } from 'src/app/data/model/product/ProductModel';
import { ProductService } from '../../../../../data/service/product/product.service';

@Component({
  selector: 'app-update-product-video',
  templateUrl: './update-product-video.component.html',
  styleUrls: ['./update-product-video.component.scss']
})
export class UpdateProductVideoComponent implements OnInit {

  segmentSelected = 'Add';
  searchTitle = '';
  selectedCourseId = 0;
  courseSelected = false;
  courseDetail: IProductDetailModel;
  course: IProductModel;
  filteredCourses: IProductFilterModel;
  updateVideoForm: FormGroup;
  addVideoForm: FormGroup;
  selectedVideoIndex = -1;
  empty = false;

  constructor(
    private courseService: ProductService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    public alertController: AlertController,
    private router: Router) { }

  ngOnInit(): void {

    this.updateVideoForm = this.fb.group({
      videoName: ['', [Validators.required, Validators.minLength(5), Validators.maxLength(1000000)]],
      videoDescription: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      videoUrl: ['', [Validators.required, Validators.minLength(5), Validators.maxLength(1000000)]],
      videoUrlOnline: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      videoTime: ['00:00', [Validators.required, Validators.minLength(5), Validators.maxLength(5)]],
      isFree: [false, [Validators.required]],
      isAparat: [false, [Validators.required]],
      isFile: [false, [Validators.required]],
      hasPrediction: [false, [Validators.required]],
      hasPredictionOnline: [false, [Validators.required]]
    });

    this.addVideoForm = this.fb.group({
      videoName: ['', [Validators.required, Validators.minLength(5), Validators.maxLength(1000000)]],
      videoDescription: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      videoUrl: ['', [Validators.required, Validators.minLength(5), Validators.maxLength(1000000)]],
      videoUrlOnline: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      videoTime: ['00:00', [Validators.required, Validators.minLength(5), Validators.maxLength(5)]],
      isFree: [false, [Validators.required]],
      isAparat: [false, [Validators.required]],
      isFile: [false, [Validators.required]],
      hasPrediction: [false, [Validators.required]],
      hasPredictionOnline: [false, [Validators.required]]
    });

    let filter: IProductFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;
      const startPrice = params.startPrice ? params.startPrice : null;
      const endPrice = params.endPrice ? params.endPrice : null;
      const categoryIds = params.categoryIds ? params.categoryIds : [];
      const sortId = params.sortId ? params.sortId : 4;

      if (page === undefined) {
        filter = new ProductFilterModel(true, page, take, title, startPrice, endPrice, false, false, categoryIds, sortId, false);
      } else {
        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == null) {

          filter = new ProductFilterModel(false, page, take, title);
        } else {
          filter =
            new ProductFilterModel(true, page, take, title, startPrice, endPrice, false, false, categoryIds, sortId, false);
        }
      }
      this.filteredCourses = filter;

      SharedIonic.loading(this.loadingController);

      this.courseService.GetAdminProductsByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredCourses = res.data;
          } else {
            this.empty = true;
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  onSelectVideo(index: number | string): void {

    this.selectedVideoIndex = +index;

    this.updateVideoForm.setValue({
      videoName: this.courseDetail.productVideos[+index].courseTitle,
      videoDescription: this.courseDetail.productVideos[+index].videoDescription,
      videoUrl: this.courseDetail.productVideos[+index].videoUrl,
      videoUrlOnline: this.courseDetail.productVideos[+index].videoUrlOnline,
      videoTime: this.courseDetail.productVideos[+index].videoTime,
      isFree: this.courseDetail.productVideos[+index].isFree,
      isAparat: this.courseDetail.productVideos[+index].isAparat,
      isFile: this.courseDetail.productVideos[+index].isFile,
      hasPrediction: this.courseDetail.productVideos[+index].hasPrediction,
      hasPredictionOnline: this.courseDetail.productVideos[+index].hasPredictionOnline
    });
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به درج هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm(index) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onDelete(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onDelete(index: number | string): void {

    this.selectedVideoIndex = +index;

    SharedIonic.loading(this.loadingController);

    this.courseService.AdminDeleteProductVideo(this.courseDetail.productVideos[this.selectedVideoIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.courseDetail.productVideos.splice(this.selectedVideoIndex, 1);

          this.updateVideoForm.setValue({
            videoName: '',
            videoDescription: '',
            videoUrl: '',
            videoUrlOnline: '',
            videoTime: '00:00',
            isFree: false,
            isAparat: false,
            isFile: false,
            hasPrediction: false,
            hasPredictionOnline: false
          });
          // this.selectedCourseId = 0;
          // this.courseSelected = false;
          // this.setQueryParams(1);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onUpdate() {

    if (this.updateVideoForm.valid || this.selectedVideoIndex != -1) {

      SharedIonic.loading(this.loadingController);

      let video = new ProductVideoModel(
        this.courseDetail.productVideos[this.selectedVideoIndex].id,
        false,
        this.updateVideoForm.value.videoName,
        this.updateVideoForm.value.videoUrl,
        this.updateVideoForm.value.videoTime,
        this.updateVideoForm.value.isFree,
        this.updateVideoForm.value.videoDescription,
        this.updateVideoForm.value.isFile,
        this.updateVideoForm.value.isAparat,
        this.updateVideoForm.value.videoUrlOnline,
        this.updateVideoForm.value.hasPrediction,
        this.updateVideoForm.value.hasPredictionOnline
      );

      this.courseService.AdminAddOrUpdateProductVideo(
        new AddOrUpdateProductVideoModel(
          this.courseDetail.id,
          video
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.courseDetail.productVideos[this.selectedVideoIndex].courseTitle = this.updateVideoForm.value.videoName;
            this.courseDetail.productVideos[this.selectedVideoIndex].isAparat = this.updateVideoForm.value.isAparat;
            this.courseDetail.productVideos[this.selectedVideoIndex].isFile = this.updateVideoForm.value.isFile;
            this.courseDetail.productVideos[this.selectedVideoIndex].isFree = this.updateVideoForm.value.isFree;
            this.courseDetail.productVideos[this.selectedVideoIndex].videoDescription = this.updateVideoForm.value.videoDescription;
            this.courseDetail.productVideos[this.selectedVideoIndex].videoTime = this.updateVideoForm.value.videoTime;
            this.courseDetail.productVideos[this.selectedVideoIndex].videoUrl = this.updateVideoForm.value.videoUrl;
            this.courseDetail.productVideos[this.selectedVideoIndex].videoUrlOnline = this.updateVideoForm.value.videoUrlOnline;
            this.courseDetail.productVideos[this.selectedVideoIndex].hasPrediction = this.updateVideoForm.value.hasPrediction;
            this.courseDetail.productVideos[this.selectedVideoIndex].hasPredictionOnline = this.updateVideoForm.value.hasPredictionOnline;

            this.updateVideoForm.setValue({
              videoName: '',
              videoDescription: '',
              videoUrl: '',
              videoUrlOnline: '',
              videoTime: '00:00',
              isFree: false,
              isAparat: false,
              isFile: false,
              hasPrediction: false,
              hasPredictionOnline: false
            });
            this.selectedVideoIndex = -1;
            // this.onSelectItem(this.course);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd() {

    if (this.addVideoForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.courseService.AdminAddOrUpdateProductVideo(
        new AddOrUpdateProductVideoModel(
          this.courseDetail.id,
          new ProductVideoModel(
            null,
            false,
            this.addVideoForm.value.videoName,
            this.addVideoForm.value.videoUrl,
            this.addVideoForm.value.videoTime,
            this.addVideoForm.value.isFree,
            this.addVideoForm.value.videoDescription,
            this.addVideoForm.value.isFile,
            this.addVideoForm.value.isAparat,
            this.addVideoForm.value.videoUrlOnline,
            this.addVideoForm.value.hasPrediction,
            this.addVideoForm.value.hasPredictionOnline
          )
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.addVideoForm.setValue({
              videoName: '',
              videoDescription: '',
              videoUrl: '',
              videoUrlOnline: '',
              videoTime: '00:00',
              isFree: false,
              isAparat: false,
              isFile: false,
              hasPrediction: false,
              hasPredictionOnline: false
            });
            this.onSelectItem(this.course);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredCourses.startPage == null) {
      return;
    }
    if (this.filteredCourses.pageId > this.filteredCourses.startPage && +this.filteredCourses.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredCourses.title = this.searchTitle;

    this.router
      .navigate(
        ['SuperAdminPanel', 'UpdateProductVideo'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredCourses.takeEntity ? this.filteredCourses.takeEntity : null,
            title: this.filteredCourses.title ? this.filteredCourses.title : null,
            startPrice: this.filteredCourses.startPrice ? this.filteredCourses.startPrice : null,
            endPrice: this.filteredCourses.endPrice ? this.filteredCourses.endPrice : null,
            categoryIds: this.filteredCourses.categoryIds ? this.filteredCourses.categoryIds : [],
            sortId: this.filteredCourses.sortId ? this.filteredCourses.sortId : 0
          }
        });
  }

  onSelectItem(model: IProductModel) {

    this.selectedCourseId = +model.id;
    this.course = model;

    // tslint:disable-next-line: max-line-length
    this.courseDetail = new ProductDetailModel(this.selectedCourseId, model.name, model.price, model.offPrice, 0, model.shortDescription, model.description, '', false, false, model.createDate, model.lastUpdateDate, false, [], false, model.seller);

    SharedIonic.loading(this.loadingController);

    this.courseService.GetAdminProductDetailVideosById(this.selectedCourseId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          const video = [];

          res.data.forEach(v => {
            video.push(
              // tslint:disable-next-line: max-line-length
              new ProductVideoModel(v.id, v.isActive, v.courseTitle, v.videoUrl, v.videoTime, v.isFree, v.videoDescription, v.isFile, v.isAparat, v.videoUrlOnline, v.hasPrediction, v.hasPredictionOnline)
            );
          });

          this.courseDetail.productVideos = video;
          this.updateVideoForm.setValue({
            videoName: '',
            videoDescription: '',
            videoUrl: '',
            videoUrlOnline: '',
            videoTime: '00:00',
            isFree: false,
            isAparat: false,
            isFile: false,
            hasPrediction: false,
            hasPredictionOnline: false
          });
          this.courseSelected = true;
        } else {
          this.courseDetail.productVideos = [];
          this.selectedCourseId = 0;
          this.courseSelected = false;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        this.courseDetail.productVideos = [];
        this.selectedCourseId = 0;
        this.courseSelected = false;
      }
    );
  }

  onCancel() {

    this.selectedCourseId = 0;
    this.courseSelected = false;
  }
}
